      "content": "import { createUserMessage } from \"@deepseek-ai/dsh-llm/message\";\nimport { registerBridge } from \"./bridge.mjs\";\n\nexport const name = \"oma\";\nexport const inject = [];\n\nexport function apply(ctx, config = {}) {\n  registerBridge(ctx, config, createUserMessage);\n}\n"
